def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    blocked = set()
    for i in range(1, k + 1):
        xi, yi = map(int, lines[i].split())
        blocked.add((xi, yi))

    start = lines[k + 1].split()
    xs, ys = int(start[0]), int(start[1])
    direction = start[2]

    direction_map = {"NE": (-1, 1), "NW": (-1, -1), "SE": (1, 1), "SW": (1, -1)}
    dx, dy = direction_map[direction]

    if (xs, ys) in blocked:
        return "0\n"

    visited = {(xs, ys)}
    current_x, current_y = xs, ys
    seen_states = {(current_x, current_y, dx, dy)}

    count = 1

    while True:
        state = (current_x, current_y, dx, dy)
        if state in seen_states:
            break
        seen_states.add(state)

        next_x, next_y = current_x + dx, current_y + dy

        if not (1 <= next_x <= n and 1 <= next_y <= m):
            if next_x < 1 or next_x > n:
                dx = -dx
            else:
                dy = -dy
            current_x, current_y = next_x, next_y
        elif (next_x, next_y) in blocked:
            dx = -dx
            dy = -dy
            current_x, current_y = next_x, next_y
        else:
            if (next_x, next_y) not in visited:
                visited.add((next_x, next_y))
                count += 1
            current_x, current_y = next_x, next_y

    return f"{count}\n"

import collections

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = lines[1:n + 1]

    count = 0

    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    height = r2 - r1 + 1
                    width = c2 - c1 + 1

                    # Build the submatrix
                    submatrix = []
                    for i in range(r1, r2 + 1):
                        submatrix.append(matrix[i][c1:c2 + 1])

                    valid = True

                    # Check if each row can be rearranged as a palindrome
                    for row in submatrix:
                        counter = collections.Counter(row)
                        odd_count = sum(v % 2 for v in counter.values())
                        if odd_count > 1:
                            valid = False
                            break

                    if not valid:
                        continue

                    # Check if each column is a palindrome after row reordering
                    # The column palindrome check here is based on the fact that
                    # each column must form a palindrome when the rows are arranged
                    # optimally to be palindromes
                    for c in range(width):
                        col = [submatrix[r][c] for r in range(height)]
                        if col != col[::-1]:
                            valid = False
                            break

                    if valid:
                        count += 1

    return str(count) + '\n'

def solution(input_data):
    lines = input_data.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []
    for _ in range(t):
        idx += 1  # Skip empty line

        n = int(lines[idx])
        idx += 1

        tree = []
        for i in range(n):
            parts = lines[idx].split()
            idx += 1
            if parts[0] == '-1':
                tree.append({
                    'type': 'internal',
                    'l': int(parts[1]),
                    'r': int(parts[2])
                })
            else:
                tree.append({'type': 'leaf', 'value': int(parts[0])})

        # Compute number of leaves in each subtree
        leaves = [0] * n
        for i in range(n):
            node_type = tree[i]['type']
            if node_type == 'leaf':
                leaves[i] = 1
            else:
                l_child = tree[i]['l']
                r_child = tree[i]['r']
                leaves[i] = leaves[l_child] + leaves[r_child]

        # Recursive solution
        def solve(node):
            node_type = tree[node]['type']
            if node_type == 'leaf':
                return tree[node]['value']
            else:
                val1 = solve(tree[node]['l'])
                val2 = solve(tree[node]['r'])
                l_count = leaves[node]
                # Number of merges needed in this subtree is (l_count - 1)
                # If odd, Pieguy (maximizer) controls the final merge
                # If even, Piegirl (minimizer) controls the final merge
                if (l_count - 1) % 2 == 1:
                    return max(val1, val2)
                else:
                    return min(val1, val2)

        result = solve(0)
        results.append(str(result))

    return '\n'.join(results)

