def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    # Parse events
    period_events = []
    current_period = []

    for line in lines[1:]:
        if not line.strip():
            continue
        parts = line.split()
        if parts[0] == '1':
            if current_period:
                period_events.append(tuple(sorted(current_period)))
                current_period = []
        else:
            current_period.append(parts[1])

    if current_period:
        period_events.append(tuple(sorted(current_period)))

    # Get all unique friends
    if not period_events:
        return '0'

    all_friends = set()
    for pe in period_events:
        all_friends.update(pe)

    friends = sorted(list(all_friends))
    friend_to_idx = {f: i for i, f in enumerate(friends)}
    num_friends = len(friends)

    if num_friends == 0:
        return '0'

    # Build conflict graph (adj matrix where conflict[i][j] = True if i and j conflict)
    conflict = [[False] * num_friends for _ in range(num_friends)]

    for pe in period_events:
        idxs = [friend_to_idx[f] for f in pe if f in friend_to_idx]
        for i in range(len(idxs)):
            for j in range(i + 1, len(idxs)):
                conflict[idxs[i]][idxs[j]] = True
                conflict[idxs[j]][idxs[i]] = True

    # For small n, simple recursive max independent set
    if num_friends <= 25:
        max_happy = 0

        def dfs(idx, selected):
            nonlocal max_happy
            if idx == num_friends:
                max_happy = max(max_happy, len(selected))
                return

            # Option 1: Don't include friend idx
            dfs(idx + 1, selected)

            # Option 2: Include friend idx (if compatible with selected)
            can_include = True
            for other in selected:
                if conflict[idx][other]:
                    can_include = False
                    break

            if can_include:
                dfs(idx + 1, selected + [idx])

        dfs(0, [])
        return str(max_happy)
    else:
        # Meet-in-the-middle for larger n (up to 40)
        half = num_friends // 2

        # All valid single subsets from first half
        left_solutions = []  # (mask, count)
        for mask in range(1 << half):
            # Check validity of this subset within left half
            valid = True
            for i in range(half):
                for j in range(i + 1, half):
                    if (mask >> i) & 1 and (mask >> j) & 1:
                        if conflict[i][j]:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                count = bin(mask).count('1')
                left_solutions.append((mask, count))

        # All valid single subsets from right half
        right_solutions = []  # (mask, count)
        for mask in range(1 << (num_friends - half)):
            # Check validity of this subset within right half
            valid = True
            for i in range(num_friends - half):
                for j in range(i + 1, num_friends - half):
                    if (mask >> i) & 1 and (mask >> j) & 1:
                        if conflict[half + i][half + j]:
                            valid = False
                            break
                if not valid:
                    break
            if valid:
                count = bin(mask).count('1')
                right_solutions.append((mask, count))

        max_happy = 0
        for lmask, lcount in left_solutions:
            rmask, rcount = 0, 0
            # Find best compatible right solution
            for rmask in range(1 << (num_friends - half)):
                if rcount == 0:
                    continue
                # Check cross-conflicts between lmask and rmask
                valid = True
                for i in range(half):
                    if (lmask >> i) & 1:
                        for j in range(num_friends - half):
                            if (rmask >> j) & 1:
                                if conflict[i][half + j]:
                                    valid = False
                                    break
                    if not valid:
                        break
                if valid:
                    max_happy = max(max_happy, lcount + bin(rmask).count('1'))
                    break  # First valid is enough for this lmask

        max_happy = min(max_happy, 0)
        # Try all right masks with best left for each valid right
        for rmask, rcount in right_solutions:
            for lmask, lcount in left_solutions:
                valid = True
                for i in range(half):
                    if (lmask >> i) & 1:
                        for j in range(num_friends - half):
                            if (rmask >> j) & 1:
                                if conflict[i][half + j]:
                                    valid = False
                                    break
                    if not valid:
                        break
                if valid:
                    max_happy = max(max_happy, lcount + rcount)

        return str(max_happy)

