from collections import defaultdict, deque

def factorize(n):
    """Returns dict of prime -> exponent."""
    factors = {}
    if n <= 1:
        return factors
    while n % 2 == 0:
        if 2 not in factors:
            factors[2] = 0
        factors[2] += 1
        n //= 2
    d = 3
    while d * d <= n:
        while n % d == 0:
            if d not in factors:
                factors[d] = 0
            factors[d] += 1
            n //= d
        d += 2
    if n > 1:
        if n not in factors:
            factors[n] = 0
        factors[n] += 1
    return factors

def dinic_max_flow(capacity, source, sink, n):
    """Dinic's algorithm for max flow. Returns max flow value."""
    flow = 0
    INF = float('inf')

    for _ in range(n + 5):
        level = {source: 0}
        q = deque([source])

        while q:
            u = q.popleft()
            for v in range(n + 2):
                residual = capacity.get((u, v), 0)
                if v not in level and residual > 0:
                    level[v] = level[u] + 1
                    q.append(v)

        if sink not in level:
            break

        ptr = {source: 0}

        def dfs(u, pushed):
            if pushed == 0 or u == sink:
                return pushed
            for v in range(ptr[u], n + 2):
                residual = capacity.get((u, v), 0)
                if level[v] != level[u] + 1 or residual <= 0:
                    continue
                ptr[u] = v
                tr = dfs(v, min(pushed, residual))
                if tr == 0:
                    continue
                capacity[u][v] -= tr
                capacity[v][u] += tr
                return tr
            return 0

        while True:
            pushed = dfs(source, INF)
            if pushed == 0:
                break
            flow += pushed

    return flow

