        right_has = set()  # 0-indexed odd positions (1-indexed even)

        for i in range(n):
            cnt = all_factors[i].get(p, 0)
            if cnt > 0:
                if (i + 1) % 2 == 1:
                    left_has.add(i)
                else:
                    right_has.add(i)

        if not left_has or not right_has:
            continue

        source, sink = 0, n + 1
        capacity = {}

        for i in left_has:
            cnt = all_factors[i].get(p, 0)
            capacity[(source, i)] = capacity.get((source, i), 0) + cnt
            capacity[(i, source)] = -cnt

        for i in right_has:
