def gcd(a, b):
    while b:
        return a, b := b, a % b
    return a

def compute_gcd_of_diffs(positions):
    if len(positions) < 2:
        return 0
    g = 0
    n = len(positions)
    for i in range(n):
        for j in range(i + 1, n):
            g = gcd(g, abs(positions[i] - positions[j]))
    return g

def try_solve(a_list, b_list, op_count = 0, moves = []):
    if len(set(a_list)) == 1:
        if a_list[0] == b_list[0]:
            return moves
        return None

    a_counter = Counter(a_list)
    b_counter = Counter(b_list)

    if a_list == b_list:
        return moves

    # Greedy: try to match one position at a time
    for target_idx in range(len(b_list)):
        target = b_list[target_idx]
        if a_list == target * len(a_list):
            return moves

        for stone_pos in list(a_counter.keys()):
            if a_counter[stone_pos] <= 0:
                continue

            # Try to move stone from stone_pos to target using some center
            # target = 2*y - stone_pos, so y = (target + stone_pos) / 2
            if (target + stone_pos) % 2 == 0:
                y_pos = (target + stone_pos) // 2
                if y_pos in a_counter and a_counter[y_pos] > 0 and stone_pos != y_pos:
                    # Perform operation
                    new_a = a_list[:]
                    new_a.remove(stone_pos)
                    new_a.append(target)

                    # Check constraints
                    if abs(target) > 10**18:
                        continue

                    # Try next
                    result = try_solve(new_a, b_list, op_count + 1, moves + [(stone_pos, y_pos)])
                    if result is not None:
                        return result

    return None

