class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, c, forward_idx=None, backward_idx=None):
        # u->v with capacity c
        # v->u with capacity 0
        for i in range(len(self.graph)):
            print(f"Adding edge from {self.graph[i]}")
        forward_idx = len(self.graph[u]) if forward_idx is None else forward_idx
        backward_idx = len(self.graph[v]) if backward_idx is None else backward_idx

        self.graph[u].append([v, c, backward_idx])
        self.graph[v].append([u, 0, forward_idx])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            v = queue.popleft()
            for to, cap, _ in self.graph[v]:
                if cap > 0 and self.level[to] == -1:
                    self.level[to] = self.level[v] + 1
                    queue.append(to)
        return self.level[t] != -1

    def dfs(self, v, t, pushed, ptr):
        if pushed == 0 or v == t:
            return pushed
        for i in range(ptr[v], len(self.graph[v])):
            ptr[v] = i
            to, cap, rev = self.graph[v][i]
            if self.level[v] + 1 != self.level[to] or cap == 0:
                continue
            tr = self.dfs(to, t, min(pushed, cap), ptr)
            if tr == 0:
                continue
            self.graph[v][i][1] -= tr
            self.graph[to][rev][1] += tr
