    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    # Special case for k = 0: we need max consecutive N's to be exactly 0
    # This is possible iff there are no 'N' characters (we can turn all '?' to 'Y')
    if k == 0:
        return 'YES\n' if 'N' not in s else 'NO\n'

    # dp[(j, o)] = is it possible to have j consecutive N's at current position
    # with o indicating whether we've seen k consecutive N's at some point
    # j ranges from 0 to k (we never allow > k consecutive N's)
    dp = set()
    dp.add((0, 0))

    for char in s:
        new_dp = set()

        # Treat this position as 'Y' (allowed if char is 'Y' or '?')
        if char in ('Y', '?'):
            for (j, o) in dp:
                new_dp.add((0, o))
            if not new_dp:
                continue

        # Treat this position as 'N' (allowed if char is 'N' or '?')
        if char in ('N', '?'):
            for (j, o) in dp:
                new_j = j + 1
                if new_j <= k:
                    new_o = 1 if new_j == k else o
                    new_dp.add((new_j, new_o))

        dp = new_dp
        if not dp:
            return 'NO\n'

    # Check if any valid configuration has seen exactly k consecutive N's without exceeding it
    return 'YES\n' if any(o == 1 for (j, o) in dp) else 'NO\n'

