    if n % 2 != 0:
        return '-1\n'

    def is_stable(m):
        """Check if matching m is stable"""
        partner = {}
        for i in range(n):
            if m[i] != -1:
                j = m[i] - 1
                partner[i] = j
                partner[j] = i

        # Check for blocking pairs
        for i in range(n):
            p_i = partner.get(i)
            if p_i is None:
                return False

            for j in range(i + 1, n):
                p_j = partner.get(j)
                if p_j is None:
                    continue

                # (i,j) is blocking if both prefer each other over current partners
                if costs[i][j] < costs[i][p_i] and costs[j][i] < costs[j][p_j]:
                    return False

        return True

    def find_stable_matching():
        """Find stable matching using greedy + backtracking"""
        matching = [-1] * n

        for attempt in range(1000):
            random.seed(attempt)

            # Initialize with greedy matching
            matched = set()
            first_unmatched = -1

            # Find first unassigned
            for i in range(n):
                if matching[i] == -1:
                    first_unmatched = i
                    break

            # Greedy matching
            greedily_matched = 0

            while first_unmatched != -1:
                for j in range(first_unmatched + 1, n):
                    if matching[j] == -1 and first_unmatched < j:
                        matching[first_unmatched] = j + 1
                        matching[j] = first_unmatched + 1
                        greedily_matched += 2
                        first_unmatched = -1
                        break
                else:
                    # Shuffle and try again  
                    shuffling_indices = [i for i in range(n) if matching[i] == -1]
                    if len(shuffling_indices) > 1:
                        random.shuffle(shuffling_indices)
                        for idx in shuffling_indices:
                            matching[idx] = -1

            if is_stable(matching):
                return matching

            # Reset and try different order
            random.shuffle(range(n))

            # Backtracking search
            if backtrack_matching(matching):
                return matching

        return None

    def backtrack_matching(matching):
        """Backtracking search for stable matching"""
        n_local = n
        costs_local = costs

        # Memoization
        memo = set()

        def check_stable(m):
            partner = {}
            for i in range(n):
