                    partner[i] = j
                    partner[j] = i

            for i in range(n):
                p_i = partner.get(i)
                if p_i is None:
                    return False
                for j in range(i + 1, n):
                    p_j = partner.get(j)
                    if p_j is None:
                        continue
                    if costs_local[i][j] < costs_local[i][p_i] and costs_local[j][i] < costs_local[j][p_j]:
                        return False
            return True

        result = [-1] * n
        visited = set()
