            if depth > n // 2 + 10:
                return False
            depth += 1

            # Find first unassigned
            for i in range(n):
                if curr[i] == -1:
                    first = i
                    break

            if all(curr[i] != -1 for i in range(n)):
                return check_stable(curr)

            # Try pairing first with each unassigned j
            for j in range(first + 1, n):
                if curr[j] == -1:
                    curr[first] = j + 1
                    curr[j] = first + 1

                    if search(curr):
