from collections import deque, defaultdict

def get_distances(adj, start, n):
    dist = [-1] * (n + 1)
    dist[start] = 0
    q = deque([start])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

def get_diameter_path(adj, n):
    dist1 = get_distances(adj, 1, n)
    if n == 1:
        return [1], 0

    furthest = max(range(1, n + 1), key=lambda x: dist1[x])
    dist2 = get_distances(adj, furthest, n)

    parent = [-1] * (n + 1)
    dist = [-1] * (n + 1)
    dist[1] = 0
    q = deque([1])

    while q:
        u = q.popleft()
        if u == furthest:
            break
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                parent[v] = u
                q.append(v)

    path = []
    curr = furthest
    while curr != -1:
        path.append(curr)
        curr = parent[curr]
    return path[::-1], max(dist2)

